import networkx as nx

G = nx.tutte_coxeter_graph()
print("Nodes:", G.number_of_nodes())
print("Edges:", G.number_of_edges())
print("Bipartite:", nx.is_bipartite(G))
try:
    cycles = nx.cycle_basis(G)
    min_cycle = min(len(c) for c in cycles)
    print("Min cycle in basis:", min_cycle)
except:
    pass

# Let's compute the exact girth
def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        # BFS to find shortest cycle
        dist = {n: 0}
        queue = [n]
        parent = {n: None}
        while queue:
            curr = queue.pop(0)
            for neighbor in G.neighbors(curr):
                if neighbor not in dist:
                    dist[neighbor] = dist[curr] + 1
                    parent[neighbor] = curr
                    queue.append(neighbor)
                elif parent[curr] != neighbor:
                    girth = min(girth, dist[curr] + dist[neighbor] + 1)
    return girth

print("Girth:", get_girth(G))

