def find_graph():
    V = 30
    E_target = 33

    for attempt in range(10000):
        adj = {i: [] for i in range(V)}
        edges = []

        # To make it bipartite, divide into two sets of 15
        set1 = list(range(15))
        set2 = list(range(15, 30))

        possible_edges = [(u, v) for u in set1 for v in set2]
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            # Check if adding (u, v) creates a cycle of length <= 6
            # Since it's bipartite, cycles can only be of length 4 or 6.
            # So we just need to check if distance between u and v is <= 5.

            # BFS from u
            dist = {u: 0}
            queue = [u]
            found_short_path = False
            while queue:
                curr = queue.pop(0)
                if dist[curr] >= 5:
                    continue
                for neighbor in adj[curr]:
                    if neighbor == v:
                        found_short_path = True
                        break
                    if neighbor not in dist:
                        dist[neighbor] = dist[curr] + 1
                        queue.append(neighbor)
                if found_short_path:
                    break

            if not found_short_path:
                adj[u].append(v)
                adj[v].append(u)
                edges.append((u, v))
                if len(edges) == E_target:
                    return edges

    return None

